  exactObject(payload.safety, safetyKeys, 'safety');
  if (!Number.isInteger(payload.stepIndex) || payload.stepIndex < 0 || payload.stepIndex > STEPS.length) throw new TypeError('단계 번호가 올바르지 않습니다.');
