    case 'incomplete':
      text = '아직 필수 조치가 끝나지 않았습니다. 빠진 단계를 완료한 뒤 작업에 들어가세요. 현실에는 되감기가 없습니다.';
      break;
    case 'wrong': {
      const reason = sentences(result.reason)[0] ?? '위험한 에너지가 남은 상태로 작업에 들어갔습니다.';
      text = `${reason} 작업 전에 차단·잠금과 잔류 에너지 안전조치 및 차단 확인을 완료해야 합니다. 현실에는 되감기가 없습니다.`;
      break;
    }
